const findTopInPkg = (pkgName: string, name: string): string | undefined => {
    const files = pkgFiles.get(pkgName);
    if (!files) return undefined;
    for (const f of files) {
      const sym = table.topLevelSymbol(f, name);
      if (sym) return sym.id;
    }
    return undefined;
  };
